    Fee.objects.filter(balance__lt=0, status__in=["pending", "overdue"]).update(
        balance=0, status="paid"
    )
    Fee.objects.filter(balance__lt=0).update(balance=0)
    Fee.objects.filter(balance__gt=F("total_amount")).update(
        balance=F("total_amount")
    )


